cd /tmp/vally-eval-trial-q1gZQE && cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
mkdir tests/CheckoutPricing.IntegrationTests/Checkout && cat > tests/CheckoutPricing.IntegrationTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysTotal95()
    {
        var total = new Application.Checkout().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | tail -25

